/**
 * Learner-facing evaluation response submission.
 * @module     local_airpay_evaluation/response_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_evaluation/response_actions", [
    "core/str",
    "core/notification",
    "core/ajax"
], function(Str, Notification, Ajax) {
    "use strict";

    var collectAnswers = function(root) {
        var cards = root.querySelectorAll(".question-card");
        var answers = {};
        var missing = null;

        for (var i = 0; i < cards.length; i++) {
            var card = cards[i];
            var qid = card.dataset.questionid;
            var qtype = card.dataset.questiontype;
            var required = card.dataset.required === "1";
            var value = null;

            if (qtype === "text") {
                var ta = card.querySelector("textarea");
                value = ta ? ta.value.trim() : "";
            } else {
                var checked = card.querySelector('input[type="radio"]:checked');
                value = checked ? checked.value : null;
            }

            if (required && (value === null || value === "")) {
                missing = card;
                break;
            }

            if (value !== null && value !== "") {
                answers[qid] = value;
            }
        }

        return {answers: answers, missing: missing};
    };

    var submit = function(root) {
        var collected = collectAnswers(root);
        var answers = collected.answers;
        var missing = collected.missing;

        if (missing) {
            missing.scrollIntoView({behavior: "smooth", block: "center"});
            missing.style.outline = "2px solid #dc2626";
            missing.style.outlineOffset = "4px";
            setTimeout(function() {
                missing.style.outline = "";
                missing.style.outlineOffset = "";
            }, 2400);
            Str.get_string("please_answer_required", "local_airpay_evaluation").then(function(msg) {
                Notification.addNotification({message: msg, type: "warning"});
                return null;
            }).catch(Notification.exception);
            return;
        }

        var evaluationid = parseInt(root.dataset.evaluationid || "0", 10);
        var context = {
            courseid: parseInt(root.dataset.contextCourseid || "0", 10),
            programid: parseInt(root.dataset.contextProgramid || "0", 10),
            classroomid: parseInt(root.dataset.contextClassroomid || "0", 10)
        };

        var btn = root.querySelector('[data-action="submit-response"]');
        if (btn) {
            btn.disabled = true;
            btn.innerHTML = '<i class="fa fa-spinner fa-spin fa-fw"></i> Submitting...';
        }

        Ajax.call([{
            methodname: "local_airpay_evaluation_submit_response",
            args: {
                evaluationid: evaluationid,
                answers: JSON.stringify(answers),
                context: JSON.stringify(context)
            }
        }])[0].then(function() {
            Str.get_string("response_submitted", "local_airpay_evaluation").then(function(msg) {
                Notification.addNotification({message: msg, type: "success"});
                setTimeout(function() { window.location.reload(); }, 600);
                return null;
            }).catch(Notification.exception);
            return null;
        }).catch(function(err) {
            Notification.exception(err);
            if (btn) {
                btn.disabled = false;
                btn.innerHTML = '<i class="fa fa-paper-plane fa-fw"></i> Submit Response';
            }
        });
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        if (trigger.dataset.action !== "submit-response") return;
        event.preventDefault();
        var root = document.querySelector('[data-region="airpay-eval-respond"]');
        if (root) submit(root);
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-eval-respond"]');
            if (!root || root.dataset.airpayResponseInit === "1") return;
            root.dataset.airpayResponseInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
